import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback

flowFile = session.get()
if (!flowFile) {
    session.transfer(flowFile, REL_FAILURE)
    return
}
def modelName=flowFile.getAttribute('modelName')?.trim()
if(!modelName){
    session.transfer(flowFile, REL_FAILURE)
    return
}
def platform=flowFile.getAttribute('platform')?.trim()
if(!platform){  
    session.transfer(flowFile, REL_FAILURE)
    return
}   
def hasError = false
flowFile = session.write(flowFile, { inputStream, outputStream ->
    def contentData = new String(inputStream.bytes, StandardCharsets.UTF_8)

    // Kiểm tra content có null hoặc rỗng không
    if (!contentData || contentData.trim().isEmpty()) {
        hasError = true
        return
    }

    // Parse JSON từ contentData
    def jsonSlurper = new JsonSlurper()
    def jsonData = jsonSlurper.parseText(contentData)
    def jsonString= JsonOutput.toJson(jsonData)
    def actualResult=[:]
    actualResult.put('modelName', modelName)
    actualResult.put('actualResult', jsonString)
    actualResult.put('platform', platform)

    outputStream.write(JsonOutput.prettyPrint(JsonOutput.toJson(actualResult)).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

session.transfer(flowFile, hasError ? REL_FAILURE : REL_SUCCESS)

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.time.Instant
import java.time.ZoneId
import java.time.LocalDateTime


flowFile = session.get()
if (!flowFile) return

def content = ''
session.read(flowFile, { inputStream -> content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content == "null") {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def jsonArray = new JsonSlurper().parseText(content)
if (!(jsonArray instanceof List)) {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def processedArray = jsonArray.collect { json ->
    if (json.containsKey('platform')) {
        def attachments = []

        json.post_id = json.ad_id
        json.post_unique_id = json.ad_id

        if (json.containsKey("post") && json.post.containsKey("post_time") && json.post.post_time != null) {
            json.post.post_time = Instant.ofEpochSecond(json.post.post_time)
                    .atZone(ZoneId.of("Asia/Ho_Chi_Minh"))
                    .toLocalDateTime().toString()
        }

        if (json.containsKey('image') && json.image) {
            def pattern = /(https?:[^"\\]+)/

            def match = (json.image =~ pattern)
            if (match) {
                def url = match[0][1]
                attachments << [image_url: url, type: "image"]
            }
        }
        json.post.attachments = attachments
        json.remove('image')

        json.post?.platform = json.platform
        json.post?.profile?.platform = json.platform
    }
    return json
}

flowFile = session.write(flowFile, { outputStream -> outputStream.write(JsonOutput.toJson(processedArray).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

import org.jsoup.Jsoup
import groovy.json.JsonSlurper
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback
import groovy.json.JsonOutput

def flowFile = session.get()
if (!flowFile) return

def fromHtml(String html) {
    def nodes = []
    def soup = Jsoup.parse(html)
    def scripts = soup.select("script")

    scripts.each { script ->
        def jsonObjects = fromText(script.html())
        nodes.add(jsonObjects)
    }

    scripts = soup.select("pre")

    scripts.each { script ->
        def jsonObjects = fromText(script.html())
        nodes.add(jsonObjects)
    }

    return nodes
}

def findCompleteJson(text, startIndex) {
    int openBraces = 0
    int closeBraces = 0
    for (int i = startIndex; i < text.length(); i++) {
        if (text[i] == '{') openBraces++
        if (text[i] == '}') closeBraces++
        if (openBraces > 0 && openBraces == closeBraces) {
            return text.substring(startIndex, i + 1)
        }
    }
    throw new IllegalArgumentException("Không tìm thấy JSON hoàn chỉnh từ vị trí $startIndex")
}

def fromText(text) {
    def res = []
    def pos = 0
    while (pos < text.length()) {
        def match = text.indexOf('{', pos)
        if (match == -1) break
        try {
            def jsonText = findCompleteJson(text, match)
            def result = new JsonSlurper().parseText(jsonText)
            res << result
            pos = match + jsonText.length()
        } catch (Exception e) {
            pos = match + 1
        }
    }
    return res
}

def findNodes(key, dataInput) {
    if (dataInput instanceof Map) {
        dataInput.each { k, v ->
            if (k == key) {
                yield v
            } else if (v instanceof Map || v instanceof List) {
                yieldAll findNodes(key, v)
            }
        }
    } else if (dataInput instanceof List) {
        dataInput.each { item -> yieldAll findNodes(key, item)
        }
    }
}

def findNode(key, dataInput) {
    def nodes = findNodes(key, dataInput)
    return nodes ? nodes[0] : null
}

