import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.security.MessageDigest

flowFile = session.get()
if (!flowFile) return

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content == "null") {
    session.transfer(flowFile, REL_FAILURE)
    return
}

json = new JsonSlurper().parseText(content)

if (json.containsKey('image_download_url')) {
    json.image_download_url = "https://adslibrary.eu-central-1.linodeobjects.com/${json.image_download_url}"
    def id = getID(json.image_download_url)
    json.image_id = id
    json.type = 'avatar_image'

    json.platform = json['0'].toLowerCase()
    if (json.platform == 'facebook') {
        json.platform = 'facebook.com'
    }
    json.remove('0')
    flowFile = session.write(flowFile, {outputStream ->
        outputStream.write(JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8))
    } as OutputStreamCallback)

    session.transfer(flowFile, REL_SUCCESS)
} else {
    session.transfer(flowFile, REL_FAILURE)
}

def getID(String url) {
    def uri = new URI(url)
    def path = uri.path
    def md5 = MessageDigest.getInstance("MD5")
    def hashBytes = md5.digest(path.bytes)
    return hashBytes.collect { String.format("%02x", it) }.join('')
}

