import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

def mapPlatforms = [10: "facebook", 3: "facebook"]

flowFile = session.get()
if (!flowFile) return

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content == "null") {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def jsonArray = new JsonSlurper().parseText(content)
if (!(jsonArray instanceof List)) {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def processedArray = jsonArray.collect { json ->
    if (json.containsKey('platform') && mapPlatforms.containsKey(json.platform)) {
        def attachments = []
        json.platform = mapPlatforms[json.platform]
        json.post_id = json.ad_id
        json.post_unique_id = json.ad_id

        if ((!json.containsKey('url') || !json.url) && json.post?.url) {
            json.url = json.post.url
        }

        if (json.containsKey('image') && json.image) {
            if (json.image.contains('video')) {
                attachments << [video_url: json.image, type: "video"]
            } else {
                attachments << [image_url: json.image, type: "image"]
            }
        }
        if (json.containsKey('video') && json.video) { // thumbnail video
            attachments << [image_url: "https://media.poweradspy.com/${json.video}", type: "image"]
        }

        if (json.containsKey("array_attachments")) {
            if (json.array_attachments instanceof String) {
                try {
                    json.array_attachments = new JsonSlurper().parseText(json.array_attachments) as List<String>
                } catch (Exception e) {
                    json.array_attachments = []
                }
            }
        }

        if (json.array_attachments instanceof List) {
            json.array_attachments.each { imageUrl ->
                attachments << [image_url: "https://media.poweradspy.com/${imageUrl}", type: "image"]
            }
        }
        json.post.attachments = attachments
        json.remove('video')
        json.remove('image')
        json.remove('array_attachments')

        json.post.domain = "facebook.com"
        json.post?.platform = json.platform
        json.post?.profile?.platform = json.platform
    }
    return json
}

flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(JsonOutput.toJson(processedArray).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

