import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback

flowFile = session.get()
if (!flowFile) return

def content = ''
def adminId= flowFile.getAttribute('AdminId')?.trim()
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

// Xoá flowFile nếu content null, "null", hoặc rỗng
if (content == null || content.trim() == '' || content.trim().toLowerCase() == 'null') {
    session.remove(flowFile)
    return
}

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def jsonArr = new JsonSlurper().parseText(content)
    def resultArr = []

    for (int i = 0; i < jsonArr.size(); i++) {
        def item = jsonArr[i]

        // Xoá actor_id nếu null, "null", "", hoặc toàn khoảng trắng
        if (item.containsKey('actor_id')) {
            def aid = item.actor_id
            if (aid == null || aid.toString().trim().toLowerCase() == 'null' || aid.toString().trim() == '') {
                item.remove('actor_id')
            }
        }


        if (item.containsKey('created_time')) {
            def createdTime = item.created_time
            if (createdTime instanceof String) {
                // Xử lý ISO datetime string -> lưu thành giây (10 chữ số)
                try {
                    def date = Date.parse("yyyy-MM-dd'T'HH:mm:ss.SSSSSSXXX", createdTime)
                    item.created_time = (long)(date.getTime() / 1000L)
                } catch (Exception e) {
                    // Nếu không parse được ISO format, thử format khác
                    try {
                        def date = Date.parse("yyyy-MM-dd'T'HH:mm:ss.SSSXXX", createdTime)
                        item.created_time = (long)(date.getTime() / 1000L)
                    } catch (Exception e2) {
                        // Giữ nguyên nếu không parse được
                    }
                }
            } else if (createdTime instanceof Number) {
                def createdStr = createdTime.toString()
                 if (createdStr.length() == 13) {
                    // Nếu đã là 13 số (milliseconds), chuyển về giây (chia 1000)
                    try {
                        long ts = createdTime.toLong()
                        item.created_time = (long)(ts / 1000L)
                    } catch (e) {
                        // ignore
                    }
                }
            }
        }

        def attachment_urls = []
        def attachment_types = []

        if (item.containsKey('attachment_image') && item.attachment_image instanceof List) {
            for (int j = 0; j < item.attachment_image.size(); j++) {
                attachment_urls.add(item.attachment_image[j])
                attachment_types.add('image')
            }
        }

        if (item.containsKey('attachment_video')) {
            if (item.attachment_video instanceof String) {
                attachment_urls.add(item.attachment_video)
                attachment_types.add('video')
            } else if (item.attachment_video instanceof List) {
                for (int j = 0; j < item.attachment_video.size(); j++) {
                    attachment_urls.add(item.attachment_video[j])
                    attachment_types.add('video')
                }
            }
        }

        if (attachment_urls.size() > 0) {
            item.attachment_urls = attachment_urls
            item.attachment_types = attachment_types
        }

        // Xóa các trường attachment_image và attachment_video sau khi đã gộp
        if (item.containsKey('attachment_image')) {
            item.remove('attachment_image')
        }
        if (item.containsKey('attachment_video')) {
            item.remove('attachment_video')
        }

        item.source_type = 6
        item.crawlers=["viewer_${adminId}"]

        resultArr << item
    }

    outputStream.write(JsonOutput.toJson(resultArr).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

session.transfer(flowFile, REL_SUCCESS)

