import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback
import java.time.LocalDateTime

def flowFile = session.get()
if (!flowFile) return

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def input = inputStream.getText(StandardCharsets.UTF_8.name())
    def reviewList = new JsonSlurper().parseText(input)
    def now = LocalDateTime.now().toString()
    def flatList = []

    reviewList.each { review ->
        def reviewEpoch = review.created_at ?: System.currentTimeMillis() / 1000
        def reviewId = review.id ?: UUID.randomUUID().toString()

        // Flatten review
        def reviewDoc = review.clone()
        reviewDoc.remove('comments') // Remove comments to avoid duplication
        reviewDoc['@timestamp'] = now
        reviewDoc['parent_id'] = review.product_id
        reviewDoc['els_id'] = "${reviewId}_${(reviewEpoch / 3600).intValue()}"
        flatList << reviewDoc

        // Process comments and replies recursively
        if (review.comments instanceof List && !review.comments.isEmpty()) {
            flattenComments(review.comments, reviewId, now, flatList)
        }
    }

    def outputJson = JsonOutput.prettyPrint(JsonOutput.toJson(flatList))
    outputStream.write(outputJson.getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

// Hàm đệ quy để trải phẳng comments và replies
def flattenComments(comments, parentId, timestamp, flatList) {
    comments.each { comment ->
        def commentEpoch = comment.create_at ?: System.currentTimeMillis() / 1000
        def commentId = comment.id ?: UUID.randomUUID().toString()

        def commentDoc = comment.clone()
        commentDoc.remove('replies') // Remove replies to avoid duplication
        commentDoc['parent_id'] = parentId
        commentDoc['@timestamp'] = timestamp
        commentDoc['els_id'] = "${commentId}_${(commentEpoch / 3600).intValue()}"
        flatList << commentDoc

        // Xử lý replies nếu có
        if (comment.replies instanceof List && !comment.replies.isEmpty()) {
            flattenComments(comment.replies, commentId, timestamp, flatList)
        }
    }
}

session.transfer(flowFile, REL_SUCCESS)

