import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.text.Normalizer

// Hàm loại bỏ dấu tiếng Việt và các dấu Unicode
def removeVietnameseAccents(String str) {
    if (!str) return ""
    String temp = Normalizer.normalize(str, Normalizer.Form.NFD)
    temp = temp.replaceAll("\\p{InCombiningDiacriticalMarks}+", "")
    temp = temp.replaceAll("đ", "d").replaceAll("Đ", "d")
    return temp
}

def flowFile = session.get()
if (!flowFile) return

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def text = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    def json = new JsonSlurper().parseText(text)

    if (json instanceof Map && json.sellerName instanceof String) {
        def originalName = json.sellerName.trim()
        if (originalName) {
            def normalizedName = removeVietnameseAccents(originalName)
                .toLowerCase()
                .replaceAll("[^a-z0-9\\s-]", "") // Chỉ giữ chữ thường, số, khoảng trắng, dấu '-'
                .replaceAll("[\\s]+", "-")       // Khoảng trắng liên tiếp thành 1 dấu '-'
                .replaceAll("-{2,}", "-")         // Nếu nhiều dấu '-' liên tiếp thì gộp 1 dấu
                .replaceAll("^-|-\$", "")         // Xóa dấu '-' đầu/cuối nếu có
            json.sellerName = normalizedName
        }
    }

    outputStream.write(JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

session.transfer(flowFile, REL_SUCCESS)

