import org.apache.nifi.processor.io.StreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

def flowFile = session.get()
if (!flowFile) return

flowFile = session.write(flowFile, { inputStream, outputStream ->
    // Đọc input stream thành chuỗi
    def inputText = inputStream.getText("UTF-8")

    // Parse JSON từ chuỗi đầu vào
    def json = new JsonSlurper().parseText(inputText)

    // Danh sách chứa các URL
    def urls = []

    // Sinh các URL theo từng mục
    json.each { item ->
        def base = "https:${item.categoryUrl}"
        def cap = item.cap
        (1..60).each { page ->
            def url = "${base}/?ajax=true&isFirstRequest=true&page=${page}&spm=a211g0.flashsale.cate_${cap}.1820mHE4mHE47n"
            urls << url
        }
    }

    // Chuyển danh sách URL thành JSON
    def outputJson = JsonOutput.prettyPrint(JsonOutput.toJson([urls: urls]))

    // Ghi output ra stream
    outputStream.write(outputJson.getBytes("UTF-8"))
} as StreamCallback)

// Chuyển flowfile sang quan hệ thành công
session.transfer(flowFile, REL_SUCCESS)

