/*
 * NiFi ExecuteScript (Script Engine = Groovy)
 * Input : message {AdminId, RequestDomain, RequestUrl, Data: <__NEXT_DATA__ của thdt.vn>}
 * Output: JSON array [PostContent] (Newtonsoft deserialize được thành IEnumerable<PostContent>)
 *
 * Dynamic properties (tuỳ chọn) trên processor:
 *   source_type  : số nguyên, mặc định 0
 *   time_zone    : mặc định Asia/Ho_Chi_Minh
 */
import groovy.json.JsonGenerator
import groovy.json.JsonSlurper

import java.nio.charset.StandardCharsets
import java.time.LocalDateTime
import java.time.OffsetDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

class ThdtMapper {

    static final DateTimeFormatter SRC_TIME = DateTimeFormatter.ofPattern('dd-MM-yyyy HH:mm')
    static final DateTimeFormatter ISO_TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSXXX")

    static final JsonGenerator JSON = new JsonGenerator.Options()
            .excludeNulls()
            .disableUnicodeEscaping()
            .build()

    static String transform(String input, Integer sourceType, String timeZone) {
        def root = new JsonSlurper().parseText(input)
        String url = root.RequestUrl
        def nextData = root.Data
        if (!url || !nextData) throw new IllegalArgumentException('Thiếu RequestUrl hoặc Data')

        String slug = slugFromUrl(url) ?: nextData?.query?.slug ?: nextData?.props?.pageProps?.slug
        if (!slug) throw new IllegalArgumentException("Không lấy được slug từ ${url}")

        def queries = nextData?.props?.pageProps?.dehydratedState?.queries ?: []
        def post = findPost(queries, slug)
        if (post == null) throw new IllegalStateException("Không tìm thấy useGetPost cho slug=${slug}")

        ZoneId zone = ZoneId.of(timeZone ?: 'Asia/Ho_Chi_Minh')
        URI uri = new URI(url)

        String html = (post.content ?: '') as String
        String text = htmlToText(html)
        String shortDesc = htmlToText((post.short_description ?: '') as String)

        List<String> attachUrls = []
        List<String> attachTypes = []
        if (post.featured_img) { attachUrls << (post.featured_img as String); attachTypes << 'image' }
        extractVideos(html).each { attachUrls << it; attachTypes << 'video' }
        if (post.video_url) { attachUrls << (post.video_url as String); attachTypes << 'video' }
        if (post.youtube_id) { attachUrls << "https://www.youtube.com/watch?v=${post.youtube_id}".toString(); attachTypes << 'video' }

        def pc = [
                post_id         : post.id?.toString(),
                url             : url,
                domain          : uri.host?.replaceFirst(/^www\./, ''),
                title           : post.title,
                message         : text ?: shortDesc ?: post.title,
                message_raw     : null,
                snippet         : shortDesc ?: null,
                actor_name      : post.author ?: null,
                created_time    : toUnix(post.datetime as String, zone),
                post_type       : 'news',
                source_type     : sourceType ?: 0,
                lang            : 'vi',
                categories      : (post.categories ?: []).collect { it.name }.findAll { it },
                total_view      : post.views != null ? (post.views as long) : null,
                attachment_urls : attachUrls ?: null,
                attachment_types: attachTypes ?: null,
                crawlers        : ['NiFi.thdt.vn'],
                crawl_time      : OffsetDateTime.now(zone).format(ISO_TIME),
        ]
        return JSON.toJson([pc])
    }

    static String slugFromUrl(String url) {
        def path = new URI(url).path?.replaceAll(/\/+$/, '')
        if (!path) return null
        def last = path.substring(path.lastIndexOf('/') + 1)
        return last ? URLDecoder.decode(last, 'UTF-8') : null
    }

    // state.data của useGetPost có dạng { data: { id, slug, title, ... } }
    static Map unwrap(Object data) {
        if (!(data instanceof Map)) return null
        return data.data instanceof Map ? (Map) data.data : (Map) data
    }

    static Map findPost(List queries, String slug) {
        def byKey = queries.find { q ->
            def key = (q?.queryKey ?: [])[0]?.toString() ?: ''
            key.startsWith('useGetPost') && key.contains("\"slug\":\"${slug}\"")
        }
        def post = unwrap(byKey?.state?.data)
        if (post?.slug == slug) return post

        return queries.collect { unwrap(it?.state?.data) }.find { it?.slug == slug }
    }

    static Long toUnix(String s, ZoneId zone) {
        if (!s) return null
        try {
            return LocalDateTime.parse(s.trim(), SRC_TIME).atZone(zone).toEpochSecond()
        } catch (ignored) {
            return null
        }
    }

    static List<String> extractVideos(String html) {
        if (!html) return []
        def m = html =~ /(?i)<source[^>]+src\s*=\s*['"]([^'"]+)['"]/
        return m.collect { it[1].trim().replace(' ', '%20') }.unique()
    }

    static String htmlToText(String html) {
        if (!html) return ''
        String s = html
                .replaceAll(/(?is)<(script|style|video|audio|iframe)[^>]*>.*?<\/\1>/, ' ')
                .replaceAll(/(?i)<br\s*\/?>/, '\n')
                .replaceAll(/(?i)<\/(p|div|h[1-6]|li)>/, '\n')
                .replaceAll(/<[^>]+>/, ' ')
        s = s.replace('&nbsp;', ' ').replace('&amp;', '&').replace('&quot;', '"')
             .replace('&#039;', "'").replace('&lt;', '<').replace('&gt;', '>')
        return s.readLines().collect { it.replaceAll(/[ \t]+/, ' ').trim() }.findAll { it }.join('\n')
    }
}

if (binding.hasVariable('session')) {
    def flowFile = session.get()
    if (!flowFile) return

    Integer sourceType = binding.hasVariable('source_type') ? (source_type.value as Integer) : 0
    String timeZone = binding.hasVariable('time_zone') ? time_zone.value : 'Asia/Ho_Chi_Minh'

    try {
        String input = session.read(flowFile).withCloseable { it.getText(StandardCharsets.UTF_8.name()) }

        String output = ThdtMapper.transform(input, sourceType, timeZone)

        flowFile = session.importFrom(new ByteArrayInputStream(output.getBytes(StandardCharsets.UTF_8)), flowFile)
        flowFile = session.putAttribute(flowFile, 'mime.type', 'application/json')
        session.transfer(flowFile, REL_SUCCESS)
    } catch (Exception e) {
        log.error("THDT -> PostContent lỗi: ${e.message}", e)
        flowFile = session.putAttribute(flowFile, 'error.message', String.valueOf(e.message))
        session.transfer(flowFile, REL_FAILURE)
    }
} else {
    // Chạy thử ngoài NiFi: groovy thdt_to_postcontent.groovy <input.json> <output.json>
    new File(args[1]).setText(ThdtMapper.transform(new File(args[0]).getText('UTF-8'), 0, 'Asia/Ho_Chi_Minh'), 'UTF-8')
}

