import groovy.json.JsonOutput
import groovy.json.JsonSlurper // <-- Thêm thư viện này để đọc JSON
import java.net.HttpURLConnection
import java.net.URL
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback

def flowFile = session.get()
if (!flowFile) return

try {
    // ==========================================
    // 1. CHUẨN BỊ DỮ LIỆU
    // ==========================================
    def reqUrl = flowFile.getAttribute("RequestUrl")
    def reqHtml = flowFile.getAttribute("ResponseBody")

    def jsonMap = [
        "url": reqUrl,
        "domain": "", 
        "schema_id": "46fb2d34-53b9-41a6-b80d-9227c3d9c201",
        "schemaType": "",
        "project_id": "14b85977-cb62-4484-9ede-47071f880ff6", // ID theo curl chuẩn
        "proxy": true,
        "javascript": false,
        "headers": null,
        "html": reqHtml
    ]

    def jsonBodyString = JsonOutput.toJson(jsonMap)
    byte[] postData = jsonBodyString.getBytes(StandardCharsets.UTF_8)

    // ==========================================
    // 2. GỌI API
    // ==========================================
    def targetUrl = "http://10.9.3.70:31248/api/scrap_manager/v1/news/extract-from-html"
    URL url = new URL(targetUrl.trim()) 
    HttpURLConnection conn = (HttpURLConnection) url.openConnection()

    conn.setRequestMethod("POST")
    conn.setRequestProperty("Content-Type", "application/json-patch+json")
    conn.setRequestProperty("Accept", "*/*")
    conn.setDoOutput(true)
    conn.setConnectTimeout(15000)
    conn.setReadTimeout(60000)

    try {
        conn.getOutputStream().write(postData)
        conn.getOutputStream().flush()
    } catch (Exception e) {
        throw new Exception("Lỗi gửi request: " + e.getMessage())
    }

    // ==========================================
    // 3. XỬ LÝ KẾT QUẢ & LẤY RIÊNG "RESULT"
    // ==========================================
    int responseCode = conn.getResponseCode()
    String rawResponseText = ""

    // Đọc Raw Response
    InputStream stream = null
    try {
        if (responseCode >= 200 && responseCode < 300) {
            stream = conn.getInputStream()
        } else {
            stream = conn.getErrorStream()
        }
        if (stream != null) {
            rawResponseText = stream.getText("UTF-8")
        }
    } finally {
        if (stream != null) stream.close()
    }

    // --- LOGIC MỚI: TRÍCH XUẤT "result" ---
    String finalOutput = rawResponseText // Mặc định là raw nếu lỗi

    if (responseCode >= 200 && responseCode < 300) {
        try {
            // Parse chuỗi JSON trả về thành Object
            def jsonSlurper = new JsonSlurper()
            def parsedJson = jsonSlurper.parseText(rawResponseText)

            // Kiểm tra xem có key "result" không
            if (parsedJson instanceof Map && parsedJson.containsKey("result")) {
                // Chỉ lấy phần result
                def resultData = parsedJson.result
                // Chuyển ngược phần result thành chuỗi JSON
                finalOutput = JsonOutput.toJson(resultData)
            } else {
                // Nếu API trả về thành công nhưng không có "result" (cấu trúc lạ), giữ nguyên gốc
                log.warn("API 200 OK nhưng không tìm thấy key 'result'. Giữ nguyên response gốc.")
            }
        } catch (Exception parseEx) {
            // Nếu API trả về HTML hoặc text không phải JSON
            log.warn("Không thể parse JSON response: " + parseEx.getMessage())
        }
    }
    // --------------------------------------

    // Ghi đè kết quả (đã lọc) vào FlowFile
    def outputData = finalOutput 
    flowFile = session.write(flowFile, { inputStream, outputStream ->
        outputStream.write(outputData.getBytes(StandardCharsets.UTF_8))
    } as StreamCallback)

    // Attributes
    flowFile = session.putAttribute(flowFile, "api.status.code", String.valueOf(responseCode))

    if (responseCode >= 200 && responseCode < 300) {
        session.transfer(flowFile, REL_SUCCESS)
    } else {
        log.error("API Error ${responseCode}: ${rawResponseText}")
        session.transfer(flowFile, REL_FAILURE)
    }

} catch (e) {
    log.error("Script Error", e)
    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.commons.io.IOUtils
import java.security.MessageDigest 
import java.net.URI            
import java.text.SimpleDateFormat

// --- HÀM HỖ TRỢ ---
def cleanDomain(String domain) {
    if (!domain) return ""
    return domain.replace("https://", "").replace("http://", "").replace("www.", "").split("/")[0]
}


def getID(String url) {
    if (!url) return null

    def uri = new URI(url)
    def path = uri.path
    def md5 = MessageDigest.getInstance("MD5")
    def hashBytes = md5.digest(path.bytes)
    return hashBytes.collect { String.format("%02x", it) }.join('')
}

def resolveUrl(String rawUrl, String baseUrl) {
    if (!rawUrl) return null
    rawUrl = rawUrl.trim()

    // 1. Nếu đã là tuyệt đối -> Return luôn
    if (rawUrl.startsWith("http")) return rawUrl
    if (rawUrl.startsWith("//")) return "https:" + rawUrl

    // 2. Nếu không có baseUrl -> Không thể resolve -> Return gốc
    if (!baseUrl) return rawUrl

    try {
        if (!rawUrl.startsWith("/")) {
            String firstSegment = rawUrl.split("/", 2)[0]

            int idx = baseUrl.indexOf("/" + firstSegment + "/")

            if (idx != -1) {
                String newBase = baseUrl.substring(0, idx + 1) 
                return newBase + rawUrl
            }
        }

        URI baseUri = new URI(baseUrl)
        URI resolved = baseUri.resolve(rawUrl.replaceAll(" ", "%20"))
        return resolved.toString()
    } catch (Exception e) {
        // Cách 2: Fallback thủ công (Khi Cách 1 lỗi)
        // Lấy domain gốc: https://domain.com
        String rootDomain = ""
        if (baseUrl.startsWith("http")) {
            def parts = baseUrl.split("/")
            if (parts.length >= 3) {
                rootDomain = parts[0] + "//" + parts[2]
            }
        }

        if (rootDomain) {
            if (rawUrl.startsWith("/")) {
                // Trường hợp: /members/abc -> https://domain.com/members/abc
                return rootDomain + rawUrl
            } else {
                // Trường hợp: members/abc (không có / đầu)
                // Logic web browser: nối vào thư mục hiện tại của baseUrl
                // Ví dụ baseUrl: https://a.com/forum/index.php -> thư mục là https://a.com/forum/

                String currentDir = baseUrl
                // Nếu baseUrl không kết thúc bằng /, ta cắt bỏ phần sau dấu / cuối cùng
                if (!currentDir.endsWith("/")) {
                    int lastSlash = currentDir.lastIndexOf("/")
                    if (lastSlash > 8) { // >8 để tránh cắt nhầm http://
                        currentDir = currentDir.substring(0, lastSlash + 1)
                    } else {
                        currentDir = currentDir + "/"
                    }
                }
                return currentDir + rawUrl
            }
        }

        return rawUrl 
    }
}
def cleanUsername(String username) {
    if (!username) return null
    // Regex: tìm dấu chấm (\.) theo sau là số (\d) ở cuối chuỗi ($)
    return username.replaceAll(/\.\d+$/, "")
}

def getFirstValid(Object val) {
    if (val == null) return null

    // Nếu là List: Tìm phần tử đầu tiên khác null và không rỗng
    if (val instanceof Collection) {
        def found = val.find { item ->
            return item != null && item.toString().trim().length() > 0
        }
        return found // Trả về null nếu cả list toàn rỗng
    }

    // Nếu là String/Number đơn lẻ: Kiểm tra rỗng
    if (val.toString().trim().length() > 0) {
        return val
    }

    return null
}

def joinDescription(Object val) {
    if (val == null) return null
    if (val instanceof Collection) {
        return val.findAll { it != null && it.toString().trim().length() > 0 }.join(" ") 
    }
    return val
}

// --- LOGIC CHÍNH ---
def flowFile = session.get()
if (!flowFile) return

try {
    // 1. Lấy thông tin môi trường và Attributes
    def requestDomain = flowFile.getAttribute("domain")
    def requestUrl = flowFile.getAttribute("RequestUrl") ?: ""
    def adminId = flowFile.getAttribute("AdminId") ?: ""
    def platformName = cleanDomain(requestUrl)

    // ====================================================
    // 2. ĐỌC INPUT JSON
    // ====================================================
    def jsonText = ""
    session.read(flowFile, { inputStream ->
        jsonText = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    } as InputStreamCallback)

    def jsonSlurper = new JsonSlurper()
    def inputData = null
    try {
         inputData = jsonSlurper.parseText(jsonText)
    } catch (Exception e) {
        // Handle trường hợp JSON lỗi nếu cần
        log.error("JSON Parse Error", e)
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    def finalOutputList = []

    // ====================================================
    // PHẦN 1: XỬ LÝ IMAGE ENTITY 
    // ====================================================
    def listImages = []

    // Biến dùng chung
    def rawUsername = getFirstValid(inputData.username)
    def processedUsername = cleanUsername(rawUsername)
    def rawUid = getFirstValid(inputData.uid)

    def actorId = rawUid ?: rawUsername
    def actorName = getFirstValid(inputData.name)
    def phone = getFirstValid(inputData.phone)
    def rawLocation = getFirstValid(inputData.location)
    def timeCreation = getFirstValid(inputData.time_creation)
    def description = joinDescription(inputData.description)

    def crawlersList = null
    if (adminId && !adminId.trim().isEmpty()) {
        crawlersList = ["viewer_" + adminId]
    }
    def rawAvatarImage = getFirstValid(inputData.avatar_image)
    def rawCoverImage = getFirstValid(inputData.cover_image)
    def absAvatarUrl = resolveUrl(rawAvatarImage?.toString(), requestUrl)

    // 1.1 Avatar
    if (inputData.avatar_image) {
        if (absAvatarUrl) {
            String cleanUrl = absAvatarUrl
            if (cleanUrl.contains("?")) {
                cleanUrl = cleanUrl.split("\\?")[0]
            }

            String urlForHashing = cleanUrl.toLowerCase() 
                                          .replace("https://", "")
                                          .replace("http://", "")
                                          .replace("www.", "")

            def generatedImageId = getID(urlForHashing)

            def imageItem = [
                "platform": platformName,
                "image_download_url": absAvatarUrl,
                "image_id": generatedImageId, 
                "actor_id": actorId,
                "actor_name": actorName,
                "actor_url": requestUrl,
                "type": "avatar_image",
                "source_type": 6
            ]

            if (crawlersList) {
                imageItem["crawlers"] = crawlersList
            }

            listImages.add(imageItem)

        } 
    }

    // ĐÓNG GÓI IMAGE ENTITY
    if (listImages.size() > 0) {
        finalOutputList.add([
            "modelName": "ImageEntity",
            "actualResult": JsonOutput.toJson(listImages),
            "platform": platformName
        ])
    }

    // ====================================================
    // PHẦN 2: XỬ LÝ GRAPHQL ENTITY
    // ====================================================
    def listProfiles = []

    if (inputData.uid || inputData.username || inputData.name) {
        def profileEntity = [
            "uid": actorId,
            "platform": requestDomain ?: platformName,
            "url": requestUrl,
            "username": processedUsername,
            "name": actorName,
            "description": description,
            "profile_picture": absAvatarUrl,
            "cover_picture": rawCoverImage,
            "location": rawLocation,
            "phone": phone, 
            "time_creation": timeCreation
        ]
        listProfiles.add(profileEntity)
    }

    // ĐÓNG GÓI GRAPHQL ENTITY
    if (listProfiles.size() > 0) {
        finalOutputList.add([
            "modelName": "GraphQLEntity",
            "actualResult": JsonOutput.toJson(listProfiles),
            "platform": platformName
        ])
    }

    // ====================================================
    // PHẦN 3: XỬ LÝ USER FOLLOW ENTITY (MỚI)
    // ====================================================
    def listUserFollows = []
    def currentTime = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new Date())

    // 3.1 Xử lý Followings
    if (inputData.followings && inputData.followings instanceof Map) {
        def fUids = inputData.followings.uid
        def fNames = inputData.followings.name

        if (fUids instanceof List) {
            for (int i = 0; i < fUids.size(); i++) {
                def itemUid = fUids[i]
                if (itemUid) {
                    def itemName = (fNames instanceof List && fNames.size() > i) ? fNames[i] : ""

                    listUserFollows.add([
                        "uid": actorId,                 
                        "uid_follower": itemUid,        
                        "username": processedUsername,
                        "username_follower": itemName,
                        "platform": platformName,
                        "created_time": currentTime
                    ])
                }
            }
        }
    }

    // 3.2 Xử lý Followers 
    if (inputData.followers && inputData.followers instanceof Map) {
        def fUids = inputData.followers.uid
        def fNames = inputData.followers.name

        if (fUids instanceof List) {
            for (int i = 0; i < fUids.size(); i++) {
                def itemUid = fUids[i]
                if (itemUid) {
                    def itemName = (fNames instanceof List && fNames.size() > i) ? fNames[i] : ""

                    listUserFollows.add([
                        "uid": itemUid,                 // Người theo dõi
                        "uid_follower": actorId,        // User chính
                        "username": itemName,
                        "username_follower": processedUsername,
                        "platform": platformName,
                        "created_time": currentTime
                    ])
                }
            }
        }
    }

    // ĐÓNG GÓI USER FOLLOW ENTITY
    if (listUserFollows.size() > 0) {
        finalOutputList.add([
            "modelName": "UserFollowEntity",
            "actualResult": JsonOutput.toJson(listUserFollows),
            "platform": platformName
        ])
    }

    // ====================================================
    // PHẦN 4: XỬ LÝ URL FOLLOW ENTITY 
    // ====================================================
    def listFollowUrls = []

    // 4.1 Lấy URL từ Followings
    if (inputData.followings && inputData.followings instanceof Map) {
        def fUrls = inputData.followings.url
        if (fUrls instanceof List) {
            fUrls.each { rawLink ->
                if (rawLink) {
                    // Resolve URL từ relative sang absolute
                    def resolvedLink = resolveUrl(rawLink.toString(), requestUrl)
                    if (resolvedLink) {
                        listFollowUrls.add(resolvedLink)
                    }
                }
            }
        }
    }

    // 4.2 Lấy URL từ Followers
    if (inputData.followers && inputData.followers instanceof Map) {
        def fUrls = inputData.followers.url
        if (fUrls instanceof List) {
            fUrls.each { rawLink ->
                if (rawLink) {
                    // Resolve URL từ relative sang absolute
                    def resolvedLink = resolveUrl(rawLink.toString(), requestUrl)
                    if (resolvedLink) {
                        listFollowUrls.add(resolvedLink)
                    }
                }
            }
        }
    }

    if (listFollowUrls.size() > 0) {
        def uniqueUrls = listFollowUrls.unique()

        finalOutputList.add([
            "modelName": "UrlFollow",
            "actualResult": JsonOutput.toJson(uniqueUrls),
            "platform": platformName
        ])
    }

    // ====================================================
    // 3. GHI KẾT QUẢ RA FLOWFILE
    // ====================================================
    def finalJsonString = JsonOutput.toJson(finalOutputList)

    flowFile = session.write(flowFile, { inputStream, outputStream ->
        outputStream.write(finalJsonString.getBytes(StandardCharsets.UTF_8))
    } as StreamCallback)

    session.transfer(flowFile, REL_SUCCESS)

} catch (e) {
    log.error("Convert Script Error: " + e.getMessage(), e)
    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback // <-- Thêm thư viện này để ghi file
import org.apache.commons.io.IOUtils

def flowFile = session.get()
if (!flowFile) return

try {
    // 1. ĐỌC NỘI DUNG VÀ XÓA BOM
    def contentText = ""
    session.read(flowFile, { inputStream ->
        contentText = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    } as InputStreamCallback)

    // Xử lý xóa BOM ngay lập tức
    if (contentText != null) {
        contentText = contentText.replace('\uFEFF', '')
    } else {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // 2. PARSE JSON (Kiểm tra tính hợp lệ)
    def jsonSlurper = new JsonSlurper()
    def jsonObject = null

    try {
        jsonObject = jsonSlurper.parseText(contentText)
    } catch (Exception e) {
        log.error("Dữ liệu không phải là JSON hợp lệ", e)
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // 3. KIỂM TRA LOGIC HTML
    def responseBody = jsonObject?.ResponseBody

    // Kiểm tra rỗng
    if (!responseBody || responseBody.toString().trim().isEmpty()) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    def bodyLower = responseBody.toString().toLowerCase()
    def isHtml = bodyLower.contains("<html") || 
                 bodyLower.contains("<!doctype html") || 
                 bodyLower.contains("<head") || 
                 bodyLower.contains("<body") ||
                 bodyLower.contains("<div")

    // 4. ĐIỀU HƯỚNG
    if (isHtml) {
        // === QUAN TRỌNG: GHI LẠI CONTENT SẠCH VÀO FLOWFILE ===
        // Nếu không làm bước này, EvaluateJsonPath sẽ gặp lỗi vì file gốc vẫn chứa BOM
        def finalCleanContent = contentText
        flowFile = session.write(flowFile, { out ->
            out.write(finalCleanContent.getBytes(StandardCharsets.UTF_8))
        } as OutputStreamCallback)
        // ======================================================

        session.transfer(flowFile, REL_SUCCESS)
    } else {
        session.transfer(flowFile, REL_FAILURE)
    }

} catch (e) {
    log.error("Lỗi xử lý Script Check HTML", e)
    session.transfer(flowFile, REL_FAILURE)
}

