import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

flowFile = session.get()
if (!flowFile) return

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.readAllBytes(), StandardCharsets.UTF_8)
} as InputStreamCallback)

def jsonParser = new JsonSlurper()
def currentJson

try {
    currentJson = jsonParser.parseText(content)
} catch (Exception e) {
    session.transfer(flowFile, REL_FAILURE)
    return
}

while (true) {
    // Nếu không có key "data" → dừng và giữ currentJson
    if (!(currentJson instanceof Map) || !currentJson.containsKey("data")) {
        break
    }

    def nextData = currentJson["data"]

    // Nếu "data" là Map/List → dừng và giữ currentJson hiện tại
    if (nextData instanceof Map || nextData instanceof List) {
        break
    }

    // Nếu "data" là String → parse tiếp và gán làm currentJson mới
    if (nextData instanceof String) {
        try {
            currentJson = jsonParser.parseText(nextData)
        } catch (Exception e) {
            break
        }
    } else {
        // Không phải String/Map/List → dừng
        break
    }
}

// Ghi kết quả cuối cùng ra content
flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(JsonOutput.toJson(currentJson).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper
import groovy.json.JsonBuilder

// Lấy FlowFile từ session
flowFile = session.get()
if (!flowFile) return

// Đọc JSON từ FlowFile (giống kiểu bạn muốn)
def jsonString = ''
session.read(flowFile, { inputStream ->
    def reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8)
    jsonString = reader.text
} as InputStreamCallback)

// Parse JSON đầu vào
def parser = new JsonSlurper()
def inputJson = parser.parseText(jsonString)

// Tách thông tin từ input
def domain = inputJson.domain
def postId = inputJson.post_id
def message = inputJson.message
def sourceType = inputJson.source_type
def actorId = inputJson.actor_id
def actorName = inputJson.actor_name
def urls = inputJson.attachments_url ?: []
def types = inputJson.attachments_type ?: []

// Tạo danh sách output
def list_post = []

urls.eachWithIndex { url, i ->
    list_post << [
        platform        : domain,
        post_id         : postId,
        actor_id        : actorId,
        actor_name      : actorName,
        source_type : sourceType,
        attachment_url  : url,
        attachment_type : (i < types.size() ? types[i] : "TYPE_NOT_FOUND")
    ]
