import groovy.json.JsonSlurper
import groovy.json.JsonBuilder
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.nio.charset.StandardCharsets

// Đọc dữ liệu từ FlowFile
flowFile = session.get()
if (!flowFile) return

def jsonString = ''
session.read(flowFile, { inputStreamReader ->
    jsonString = inputStreamReader.text
} as InputStreamCallback)


// Parse JSON data
def jsonData = null
try {
    def jsonSlurper = new JsonSlurper()
    jsonData = jsonSlurper.parseText(jsonString)
    println "Successfully parsed JSON data"
} catch (Exception e) {
    println "Failed to parse JSON: ${e.message}"
    return
}

// Extract messages list
def messages = jsonData.groupMsgs
def list_post = []

println "Processing ${messages.size()} messages"

def imagePattern = ~/(?i)\.(jpg|jpeg|png|gif|bmp|webp)(\?.*)?$/
def videoPattern = ~/(?i)\.(mp4|mov|avi|wmv|flv|webm|mkv|m4v|3gp|mpeg|mpg)(\?.*)?$/
def filePattern = ~/(?i)\.(zip|rar|7z|doc|docx|xls|xlsx|ppt|pptx|pdf|txt)(\?.*)?$/

for(msg in messages){
    def createTime = (msg.ts ?: "0") as Long
    def editTime = (msg.ts ?: "0") as Long
    def post_id = msg.msgId
    def content = msg.content
    def actor_id = msg.uidFrom
    def actor_name = msg.dName
    def title = ""
    def attachments_url = []
    def attachments_type = []
    def group_id = msg.idTo

    if(content instanceof Map){
        title = content.title ?: ""

        // Xử lý content.href - có thể là string hoặc array
        if(content.href) {
            if(content.href instanceof List) {
                // Nếu href là array
                for(url in content.href) {
                    if(url && url.startsWith("http")) {
                        attachments_url << url
                    }
                }
            } else if(content.href instanceof String) {
                // Nếu href là string - có thể chứa nhiều URL
                def urls = content.href.split(',').collect { it.trim() }
                for(url in urls) {
                    if(url && url.startsWith("http")) {
                        attachments_url << url
                    }
                }
            }
        }

        // Xử lý content.thumb - tương tự
        if(content.thumb && content.thumb != content.href) {
            if(content.thumb instanceof List) {
                for(url in content.thumb) {
                    if(url && url.startsWith("http")) {
                        attachments_url << url
                    }
                }
            } else if(content.thumb instanceof String) {
                def urls = content.thumb.split(',').collect { it.trim() }
                for(url in urls) {
                    if(url && url.startsWith("http")) {
                        attachments_url << url
                    }
                }
            }
        }

        // Phân loại từng attachment
        for(attachment in attachments_url){
            if(attachment?.find(imagePattern)){
                attachments_type << "image"
            } else {
                attachments_type << "video"
            } 
        }
    } 
    else {
        title = content.toString() ?: ""
    }

    def postJson = [
        createTime: (createTime.intdiv(1000)),
        editTime: (editTime.intdiv(1000)),
        post_id: post_id,
        message: title,
        source_type:6,
        actor_id: actor_id,
        actor_name: actor_name,
        group_id: group_id,
        attachments_url: attachments_url,
        attachments_type: attachments_type
    ].findAll { it.value != null }

    list_post << postJson
}

def outputJson = new JsonBuilder(list_post).toPrettyString()

// Ghi kết quả ra FlowFile output
flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(outputJson.getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

import groovy.json.JsonSlurper
import groovy.json.JsonBuilder // Quan trọng: Sử dụng JsonBuilder
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import org.apache.nifi.processor.io.StreamCallback


flowFile = session.get()
if (!flowFile) return

def shouldFail = false

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def content = new String(inputStream.bytes, StandardCharsets.UTF_8)
    def json = new JsonSlurper().parseText(content)

    // Kiểm tra trường attachment_url
    if (!json.containsKey('attachment_url') || !json.attachment_url || !json.attachment_url.startsWith("http")) {
        shouldFail = true
        // Không ghi ra outputStream nữa
        return
    }

    def id = getID(json.attachment_url)
    if (json.containsKey('attachment_type') && json.attachment_type == 'video'){
        json.video_id = id
        json.video_download_url = json.attachment_url
        // Bỏ 2 trường attachment
        json.remove('attachment_url')
        json.remove('attachment_type')
    } else if (json.containsKey('attachment_type') && json.attachment_type == 'image'){
        json.image_id = id
        json.image_download_url = json.attachment_url
        // Bỏ 2 trường attachment
        json.remove('attachment_url')
        json.remove('attachment_type')
    }
    else{
      shouldFail = true
      return
    }

    outputStream.write(JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

// Chuyển FlowFile sang nhánh phù hợp
if (shouldFail) {
    session.transfer(flowFile, REL_FAILURE)
} else {
    session.transfer(flowFile, REL_SUCCESS)
}

def getID(String url) {
    if (!url) return null

    def uri = new URI(url)
    def path = uri.path
    def md5 = MessageDigest.getInstance("MD5")
    def hashBytes = md5.digest(path.bytes)
    return hashBytes.collect { String.format("%02x", it) }.join('')
}

