import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.nio.charset.StandardCharsets

// NiFi FlowFile Processing Script
// Read JSON data from FlowFile and output processed list

// Read input from FlowFile
def inputStream = session.get()
if (inputStream == null) {
    //log.error("No FlowFile found")
    return
}

def jsonString = ""
def jsonData = null

// Read the content from FlowFile
session.read(inputStream, { inputStreamReader ->
    jsonString = inputStreamReader.text
    //log.info("Read JSON data from FlowFile: ${jsonString.length()} characters")
} as InputStreamCallback)

// Parse JSON data
try {
    def jsonSlurper = new JsonSlurper()
    jsonData = jsonSlurper.parseText(jsonString)
    //log.info("Successfully parsed JSON data")
} catch (Exception e) {
    //log.error("Failed to parse JSON: ${e.message}")
    session.transfer(inputStream, REL_FAILURE)
    return
}

// Extract items list
def items = jsonData.data.items
def list_post = []
def group_id = jsonData.data.groupId
//log.info("Processing ${items.size()} items")

def imagePattern = ~/(?i)\.(jpg|jpeg|png|gif|bmp|webp)(\?.*)?$/
def videoPattern = ~/(?i)\.(mp4|mov|avi|wmv|flv|webm|mkv|m4v|3gp|mpeg|mpg)(\?.*)?$/

for(item in items){
    def createTime = item.createTime
    def editTime = item.editTime
    def post_id = item.id
    def post_type = item.type
    def params = item.params
    def params_json = new groovy.json.JsonSlurper().parseText(params)
    def title = params_json.title ?: ""
    def actor_id = params_json.senderUid
    def actor_name = params_json.senderName
    def client_msg_id = params_json.client_msg_id
    def global_msg_id = params_json.global_msg_id

    // Xử lý extra dạng chuỗi JSON lồng nhau
    def shared_url = null
    def shared_domain = null
    if (params_json.extra) {
        try {
            def extra = new groovy.json.JsonSlurper().parseText(params_json.extra)
            if (extra && extra.params) {
                def params_extra = new groovy.json.JsonSlurper().parseText(extra.params)
                shared_url = params_extra.href
                shared_domain = params_extra.src
            }
        } catch (Exception e) {
            // Bỏ qua nếu parse JSON extra thất bại
        }
    }
    if(shared_url && shared_url.trim()){
        title = title + (title ? "\n " : "") + shared_url
    }

    def attachments_url = params_json.thumb
    def attachments_type = null

    if (attachments_url instanceof List) {
        attachments_type = attachments_url.collect { url ->
            if (url?.toLowerCase()?.find(imagePattern)) {
                return "image"
            } else if (url?.toLowerCase()?.find(videoPattern)) {
                return "video"
            } else {
                return null
            }
        }
    } else if (attachments_url instanceof String) {
        def url = attachments_url.toLowerCase()
        if (url.find(imagePattern)) {
            attachments_type = "image"
        } else if (url.find(videoPattern)) {
            attachments_type = "video"
        }
    }

    // Create processed JSON object
    def postJson1 = [
        createTime: (createTime.intdiv(1000)),
        editTime: (editTime.intdiv(1000)),
        post_id: post_id,
        post_type:6,
        title: title,
        actor_id: actor_id,
        actor_name: actor_name,
        client_msg_id: client_msg_id,
        global_msg_id: global_msg_id,
        group_id: group_id,
        attachments_url: attachments_url,
        attachments_type: attachments_type
    ].findAll { it.value != null }

    // Add to list
    list_post << postJson1
}

// Convert list to JSON string
def outputJson = JsonOutput.prettyPrint(JsonOutput.toJson(list_post))

// Create output FlowFile
def outputFlowFile = session.create(inputStream)
outputFlowFile = session.write(outputFlowFile, { outputStream ->
    outputStream.write(outputJson.getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

// Transfer the processed FlowFile
session.transfer(outputFlowFile, REL_SUCCESS)
session.remove(inputStream)

//log.info("Successfully processed ${list_post.size()} posts")

