import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.util.regex.Pattern
import java.util.regex.Matcher
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

flowFile = session.get()
if (!flowFile) return

// read FlowFile content
def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content.trim().isEmpty()) {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def sl = new JsonSlurper()
def root
try {
    root = sl.parseText(content)
} catch (Exception e) {
    // not valid JSON -> return original content to failure
    flowFile = session.write(flowFile, { OutputStream os -> os.write(content.getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
    session.transfer(flowFile, REL_FAILURE)
    return
}

// Extract ResponseBody from root map or first element if array
def response = null
if (root instanceof Map) {
    if (root.containsKey('ResponseBody') && root.ResponseBody) response = String.valueOf(root.ResponseBody)
    else if (root.containsKey('responseBody') && root.responseBody) response = String.valueOf(root.responseBody)
} else if (root instanceof List && root.size() > 0 && root[0] instanceof Map) {
    def first = (Map) root[0]
    if (first.containsKey('ResponseBody') && first.ResponseBody) response = String.valueOf(first.ResponseBody)
    else if (first.containsKey('responseBody') && first.responseBody) response = String.valueOf(first.responseBody)
}

if (!response || !response.contains('.push(')) {
    // nothing to extract -> write original content back and fail
    flowFile = session.write(flowFile, { OutputStream os -> os.write(content.getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
    session.transfer(flowFile, REL_FAILURE)
    return
}

// find candidates: if ResponseBody is a big HTML string, use it; else, if ResponseBody not found, we could scan all string fields (optional)
def candidates = [response]

// regex for quoted .push("...") or .push('...')
def quotedPattern = Pattern.compile(/\.push\(\s*(['"])(.*?)\1\s*\)/, Pattern.DOTALL)
def results = []

for (c in candidates) {
    String resp = String.valueOf(c)
    Matcher m = quotedPattern.matcher(resp)
    while (m.find()) {
        String raw = m.group(2)
        try {
            // unescape JS string literal via JSON parser
            String unescaped = sl.parseText('"' + raw + '"')
            def parsed = sl.parseText(unescaped)
            if (parsed instanceof Map && parsed.data != null && parsed.data.viewer != null) results << parsed
        } catch (Exception ignore) { }
    }

    // also support raw object argument: .push({ ... })
    int searchIdx = 0
    while (true) {
        int pIdx = resp.indexOf('.push(', searchIdx)
        if (pIdx < 0) break
        int open = resp.indexOf('(', pIdx)
        if (open < 0) { searchIdx = pIdx + 6; continue }
        int pos = open + 1
        while (pos < resp.length() && Character.isWhitespace(resp.charAt(pos))) pos++
        if (pos >= resp.length()) break
        if (resp.charAt(pos) == '{') {
            int i = pos
            int depth = 0
            boolean inString = false
            boolean escaped = false
            while (i < resp.length()) {
                char ch = resp.charAt(i)
                if (inString) {
                    if (escaped) { escaped = false }
                    else if (ch == '\\\\') { escaped = true }
                    else if (ch == '\"') { inString = false }
                } else {
                    if (ch == '\"') { inString = true }
                    else if (ch == '{') depth++
                    else if (ch == '}') {
                        depth--
                        if (depth == 0) { i++; break }
                    }
                }
                i++
            }
            if (i > pos) {
                String rawObj = resp.substring(pos, i)
                try {
                    def parsed = sl.parseText(rawObj)
                    if (parsed instanceof Map && parsed.data != null && parsed.data.viewer != null) results << parsed
                } catch (Exception ignore) {}
            }
            searchIdx = pos + 1
        } else {
            searchIdx = pos + 1
        }
    }
}

if (results.isEmpty()) {
    // write original and fail
    flowFile = session.write(flowFile, { OutputStream os -> os.write(content.getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
    session.transfer(flowFile, REL_FAILURE)
    return
}

// write results array and success
byte[] outBytes = JsonOutput.toJson(results).getBytes(StandardCharsets.UTF_8)
flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)
session.transfer(flowFile, REL_SUCCESS)

