import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.apache.nifi.processor.io.StreamCallback
import java.nio.charset.StandardCharsets

def flowFile = session.get()
if (!flowFile) return

def shouldFail = false

flowFile = session.write(flowFile, { inputStream, outputStream ->
    try {
        def inputJson = new String(inputStream.bytes, StandardCharsets.UTF_8)

        // 1. Kiểm tra đầu vào rỗng
        if (!inputJson || inputJson.trim() == "") {
            shouldFail = true
            return
        }

        def parsed = new JsonSlurper().parseText(inputJson)

        // 2. Validate cấu trúc gốc
        // Input của bạn là Object (chứa id, edges), không phải List
        if (parsed instanceof List) {
            shouldFail = true
            return
        }

        def edges_original = parsed?.edges
        if (!edges_original || edges_original.isEmpty()) {
            shouldFail = true
            return
        }

        def resultPostHome = []

        // 3. Duyệt qua từng Edge
        for (edge in edges_original) {
            try {
                def posts = ParsePostHome(edge)
                if (posts) {
                    resultPostHome.addAll(posts)
                }
            } catch (Exception ex) {
                // Nếu lỗi 1 edge, log lại và bỏ qua, không fail toàn bộ
                // log.warn("Error parsing edge: " + ex.message)
            }
        }

        if (resultPostHome.isEmpty()) {
            shouldFail = true
            return
        }

        def outJson = JsonOutput.toJson(resultPostHome)
        outputStream.write(outJson.getBytes(StandardCharsets.UTF_8))

    } catch (Exception e) {
        shouldFail = true
    }
} as StreamCallback)

if (shouldFail) {
    session.transfer(flowFile, REL_FAILURE)
} else {
    session.transfer(flowFile, REL_SUCCESS)
}

// -----------------------------------------------------------
// CÁC HÀM XỬ LÝ (Đã tối ưu để tránh null pointer)
// -----------------------------------------------------------

def ParsePostHome(edge) {
    def listPost = []
    if (!edge || !edge.node) return listPost

    // Xử lý Stories
    def stories = edge.node.stories
    if (stories && stories instanceof List) {
        for (story in stories) {
            if (story && story.post) {
                try {
                    def post = ParsePost(story.post)
                    if (post) listPost.add(post)
                } catch (Exception e) {
                    // Bỏ qua bài post lỗi
                }
            }
        }
    }

    // Xử lý Bundle (Dữ liệu mẫu của bạn KHÔNG có bundleConnection, code cũ sẽ lỗi ở đây nếu không check null)
    def bundleEdges = edge.node.bundleConnection?.edges
    if (bundleEdges && bundleEdges instanceof List) {
        for (be in bundleEdges) {
            def node = be?.node
            if (!node) continue
            def candidate = node.answer ?: node.post ?: node
            if (candidate) {
                try {
                    def actor = ParsePost(candidate)
                    if (actor) listPost.add(actor)
                } catch (Exception e) {}
            }
        }
    }

    return listPost
}

def ParsePost(node) {
    // Validate author trước
    if (!node.author) return null

    def actor = ParseUser(node)

    return actor
}

def ParseUser(node) {
    def userContent = [:]
    def author = node.author

    userContent.put('uid', author?.uid.toString())

    def name = "Unknown"
    if (author?.names && !author.names.isEmpty()) {
        name = (author.names[0].givenName ?: "") + ' ' + (author.names[0].familyName ?: "")
    }
    userContent.put('name', name.trim())
    userContent.put('platform','quora.com')
    def profileUrl = author?.profileUrl
    if (profileUrl && !profileUrl.contains('http')) {
        profileUrl = "https://www.quora.com" + profileUrl
    }
    def username=null
    if(profileUrl){
        def parts = profileUrl.split('/')
        username = parts[-1]
    }
    userContent.put('url', profileUrl)
    userContent.put('username', username)
    userContent.put('profile_picture', author?.profileImageUrl)

    if(userContent.uid == null || userContent.uid.toString().trim() == "" || userContent.url == null || userContent.url.toString().trim() == ""){
        return null
    }

    return userContent
}

