import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.apache.nifi.processor.io.StreamCallback
import java.nio.charset.StandardCharsets

def flowFile = session.get()
if (!flowFile) return

def shouldFail = false

flowFile = session.write(flowFile, { inputStream, outputStream ->
    try {
        def inputJson = new String(inputStream.bytes, StandardCharsets.UTF_8)

        // 1. Kiểm tra đầu vào rỗng
        if (!inputJson || inputJson.trim() == "") {
            shouldFail = true
            return
        }

        def parsed = new JsonSlurper().parseText(inputJson)
        // 2. Validate cấu trúc gốc
        // Input của bạn là Object (chứa id, edges), không phải List
        if (parsed instanceof List) {
            shouldFail = true
            return
        }
        result_comments=[]
        // Support multiple possible post id fields (some payloads use `post_id`)
        def post_id = parsed?.id ?: parsed?.post_id ?: parsed?.containerId ?: parsed?.oid
        if(!post_id){
            shouldFail = true
            return
        }
        def comments_edges=parsed?.allCommentsConnection?.edges
        if(comments_edges == null || (comments_edges instanceof List && comments_edges.isEmpty())){
            shouldFail = true
            return
        }
        for(edge in (comments_edges as List)){
            ParseComment_BackTrack(edge, post_id)     
        }
        // Build a predictable output structure
        def resultPostHome = [post_id: post_id, comments: result_comments]
        def outJson = JsonOutput.toJson(result_comments)
        outputStream.write(outJson.getBytes(StandardCharsets.UTF_8))

    } catch (Exception e) {
