    session.transfer(flowFile, REL_SUCCESS)
}

def ParseComment_BackTrack(edge, post_id){
    def commentNode=edge?.node
    def commentEntity=[:]
    // Accept multiple comment id names that appear in different payloads
    def resolvedCommentId = commentNode?.commentId ?: commentNode?.comment_id ?: commentNode?.id ?: commentNode?.oid
    commentEntity.put('comment_id', resolvedCommentId)
    def commentUrl=commentNode?.url
    if(commentUrl && !commentUrl.startsWith('http')){
        commentUrl="https://www.quora.com"+commentUrl
    }
    commentEntity.put('url', commentUrl)
    commentEntity.put('post_id', post_id)
    commentEntity.put('platform', 'quora.com')

    def actor=commentNode?.user
    if(actor){
        commentEntity.put('actor_id', actor?.uid)
        commentEntity.put('actor_name', actor?.name)
        def names=actor?.names
        if(names && names instanceof List && names.size()>0){
            def fullName= names[0]?.givenName +" "+ names[0]?.familyName
            commentEntity.put('actor_username', fullName)
        }
    }
    def creationTime = commentNode?.creationTime
    if (creationTime instanceof Number) {
        // Normalize to epoch seconds (10-digit integer).
        long ct = creationTime.longValue()
        long secs
        if (ct > 1000000000000L) { // >1e12 -> likely microseconds
            secs = ct / 1000000L
        } else if (ct > 10000000000L) { // >1e10 -> milliseconds
            secs = ct / 1000L
        } else {
            secs = ct
        }

        if (secs != 0L) {
            while (secs >= 10000000000L) { secs /= 10L }
            while (secs < 1000000000L) { secs *= 10L }
        }

        commentEntity.put('created_time', secs)
    }
    def content=commentNode?.contentQtextDocument
    if(content){
        def legacyJson=content?.legacyJson
        if(legacyJson){
            def contentParsed=new JsonSlurper().parseText(legacyJson)
            if(contentParsed?.sections && contentParsed.sections.size()>0){
                def spans=contentParsed.sections[0]?.spans[0]
                commentEntity.put('content', spans?.text)
            }
        }
    }
    result_comments.add(commentEntity)
    if(commentNode?.repliesConnection){
        for(edge_reply in (commentNode?.repliesConnection?.edges as List)){
            // pass the resolved comment id to child replies
            ParseComment_BackTrack(edge_reply, commentEntity.get('comment_id'))     
        }
    }
}

import org.jsoup.Jsoup
