def adminId = flowFile.getAttribute("AdminId")?.trim() ?: null

flowFile = session.write(flowFile, { inputStream, outputStream ->
    try {
        // TỐI ƯU HIỆU NĂNG: Dùng parse(inputStream) thay vì parseText(String)
        // Giúp tránh lỗi OutOfMemory khi file JSON quá lớn
        def parsed = new JsonSlurper().parse(inputStream)

        // 1. Validate cấu trúc gốc
        if (!parsed) {
            shouldFail = true
            return
        }

        // Input gốc phải là Object (chứa edges), nếu là List [] thì sai cấu trúc
        if (parsed instanceof List) {
            shouldFail = true
            return
        }

        def edges_original = parsed?.edges
        if (!edges_original || edges_original.isEmpty()) {
            shouldFail = true
            return
        }

        def resultPostHome = []

        // 2. Duyệt qua từng Edge
        for (edge in edges_original) {
            try {
                // QUAN TRỌNG: Truyền adminId vào hàm xử lý
                def posts = ParsePostHome(edge, adminId)
                if (posts) {
                    resultPostHome.addAll(posts)
                }
            } catch (Exception ex) {
                // Log lỗi từng edge nếu cần thiết, nhưng không fail toàn bộ flowfile
                // log.warn("Error parsing edge: " + ex.message)
            }
        }

        // Nếu không lấy được bài post nào thì coi như fail
        if (resultPostHome.isEmpty()) {
            shouldFail = true
            return
        }

        // Ghi kết quả ra output
        def outJson = JsonOutput.toJson(resultPostHome)
        outputStream.write(outJson.getBytes(StandardCharsets.UTF_8))

    } catch (Exception e) {
        // Bắt lỗi cú pháp JSON hoặc lỗi hệ thống khác
        shouldFail = true
        // log.error("Global processing error: " + e.message)
    }
} as StreamCallback)

// Chuyển hướng FlowFile dựa trên kết quả xử lý
if (shouldFail) {
    session.transfer(flowFile, REL_FAILURE)
} else {
    session.transfer(flowFile, REL_SUCCESS)
}

