// Đã thêm tham số adminId
def ParsePostHome(edge, adminId) {
    def listPost = []
    if (!edge || !edge.node) return listPost

    // Xử lý Stories
    def stories = edge.node.stories
    if (stories && stories instanceof List) {
        for (story in stories) {
            if (story && story.post) {
                try {
                    // Truyền adminId xuống tầng dưới
                    def post = ParsePost(story.post, adminId)
                    if (post) listPost.add(post)
                } catch (Exception e) {
                    // Bỏ qua bài post lỗi
                }
            }
        }
    }

    // Xử lý Bundle Connection
    def bundleEdges = edge.node.bundleConnection?.edges
    if (bundleEdges && bundleEdges instanceof List) {
        for (be in bundleEdges) {
            def node = be?.node
            if (!node) continue
            // Tìm node chứa dữ liệu bài viết
            def candidate = node.answer ?: node.post ?: node.question ?: node
            if (candidate) {
                try {
                    // Truyền adminId xuống tầng dưới
                    def post = ParsePost(candidate, adminId)
                    if (post) listPost.add(post)
                } catch (Exception e) {}
            }
        }
    }

    return listPost
}

// Đã thêm tham số adminId để map vào crawlers
def ParsePost(node, adminId) {
    if (!node) return null

    // 1. Xử lý thông tin tác giả (User/Asker)
    def actor = null
    if (node?.author) {
        actor = ParseUser(node)
    } else if (node?.asker) {
        def asker = node.asker
        actor = [:]
        actor.actor_id = (asker?.uid != null) ? String.valueOf(asker.uid) : null

        def name = ''
        if (asker?.names instanceof List && !asker.names.isEmpty()) {
            def n = asker.names[0]
            def given = (n?.givenName instanceof List) ? n.givenName[0] : n?.givenName
            def family = (n?.familyName instanceof List) ? n.familyName[0] : n?.familyName
            name = ((given ?: '') + ' ' + (family ?: '')).trim()
        } else if (asker?.givenName || asker?.familyName) {
            def given = (asker?.givenName instanceof List) ? asker.givenName[0] : asker?.givenName
            def family = (asker?.familyName instanceof List) ? asker.familyName[0] : asker?.familyName
            name = ((given ?: '') + ' ' + (family ?: '')).trim()
        }
        actor.actor_name = name ?: null
        actor.actor_profileUrl = asker?.profileUrl
        actor.actor_profileImageUrl = asker?.profileImageUrl
    }

    def postContent = [:]
    postContent.put('actor_id', actor?.actor_id ?: null)
    postContent.put('actor_name', actor?.actor_name)

    // 2. Xử lý thời gian tạo (Microseconds to Seconds)
    def createdRaw = node.creationTime
    def createdSeconds = null
    if (createdRaw != null && createdRaw instanceof Number) {
        createdSeconds = (long)(createdRaw / 1000000L)
    }
    postContent.put('created_time', createdSeconds)

    postContent.put('domain', 'quora.com')
    postContent.put('source_type', 6)

    def pid = node.oid ?: node.pid ?: node.reportableId ?: node.id
    postContent.put('post_id', pid != null ? String.valueOf(pid) : null)

    postContent.put('total_like', node.numUpvotes ?: 0)
    postContent.put('total_comment', node.numDisplayComments ?: 0)
    postContent.put('total_share', node.numShares ?: 0)
    postContent.put('total_view', node.numViews ?: 0)

    // 3. Xử lý URL
    def urlPath = node.url ?: ""
    if (urlPath && !urlPath.contains('quora.com')) {
        urlPath = 'https://www.quora.com' + (urlPath.startsWith('/') ? urlPath : '/' + urlPath)
    }
    postContent.put('url', urlPath ?: null)

    // 4. Xử lý Nội dung chi tiết
    def contentMap = ParsePostContent(node)

    // Logic lấy Title: Ưu tiên lấy từ question title
    if (node.question?.title && !node.question.title.toString().trim().isEmpty()) {
        try {
            def questionTitle = new JsonSlurper().parseText(node.question.title)
            if (questionTitle?.sections && !questionTitle.sections.isEmpty() &&
                questionTitle.sections[0]?.spans && !questionTitle.sections[0].spans.isEmpty()) {
                postContent.put('title', questionTitle.sections[0].spans[0].text)
            }
        } catch (e) {
            postContent.put('title', contentMap.title ?: "")
        }
    } else {
         postContent.put('title', contentMap.title ?: "")
    }

    postContent.put('message', contentMap.message)
    postContent.put('attachment_urls', contentMap.attachment_urls)
    postContent.put('attachment_types', contentMap.attachment_types)

    // 5. Xử lý crawlers (SỬA LỖI: Dùng biến adminId được truyền vào)
    if(adminId){
        postContent.put('crawlers', ["viewer_${adminId}"])
    }

    return postContent
}

def ParsePostContent(node) {
    def result = [message: '', attachment_urls: [], attachment_types: [], title: '']

    if (!node.content || node.content.toString().trim().isEmpty()) {
        return result
    }

    try {
        // content ở đây là String JSON bên trong JSON object, nên dùng parseText là đúng
        def content = new JsonSlurper().parseText(node.content)
        def sections = content?.sections

        if (sections && !sections.isEmpty()) {
            // Lấy title backup từ span đầu tiên
            if (sections[0]?.spans && !sections[0].spans.isEmpty()) {
                result.title = sections[0].spans[0].text
            }

            def messageBuilder = new StringBuilder()

            for (section in sections) {
                if (section?.spans) {
                    for (span in section.spans) {
                        if (span?.text) {
                            messageBuilder.append(span.text)
                        }
                        // Lấy ảnh
                        if (span?.modifiers?.image) {
                             result.attachment_urls.add(span.modifiers.image)
                             result.attachment_types.add('image')
                        }
                    }
                }
            }
            result.message = messageBuilder.toString()
        }
    } catch (Exception e) {
        // Ignore parsing errors for content string
    }
    return result
}

def ParseUser(node) {
    def userContent = [:]
    def author = node.author
    def actorId = (author?.uid != null) ? String.valueOf(author.uid) : null
    userContent.put('actor_id', actorId)

    def name = 'Unknown'
    if (author?.names instanceof List && !author.names.isEmpty()) {
        def n = author.names[0]
        def given = (n?.givenName instanceof List) ? n.givenName[0] : n?.givenName
        def family = (n?.familyName instanceof List) ? n.familyName[0] : n?.familyName
        name = ((given ?: '') + ' ' + (family ?: '')).trim()
    }
    userContent.put('actor_name', name ?: null)

    userContent.put('actor_profileUrl', author?.profileUrl)
    userContent.put('actor_profileImageUrl', author?.profileImageUrl)

    return userContent
}

