import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.text.SimpleDateFormat
import java.util.Date
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback
import java.net.URI
import java.security.MessageDigest

def getID(String url) {
    if (!url) return null
    def uri = new URI(url)
    def path = uri.path
    def md5 = MessageDigest.getInstance("MD5")
    def hashBytes = md5.digest(path.bytes)
    return hashBytes.collect { String.format("%02x", it) }.join('')
}

flowFile = session.get()
if (!flowFile) {
    session.transfer(flowFile, REL_FAILURE)
    return
}

def resultArr = []

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def content = new String(inputStream.bytes, StandardCharsets.UTF_8)
    def jsonArr = new JsonSlurper().parseText(content)
    for (int i = 0; i < jsonArr.size(); i++) {
        def item = jsonArr[i]
        if (item.containsKey('attachment_urls') && item.attachment_urls instanceof List) {
            for(int j = 0; j < item.attachment_urls.size(); j++) {
                def createdTimeStr = null
                def ct = item.created_time
                Long epochSec = null
                if (ct instanceof Number) {
                    long ts = ct.toLong()
                    // Nếu là milliseconds (13 chữ số), đổi về giây
                    epochSec = (ts > 9999999999L) ? (ts / 1000L) : ts
                } else if (ct != null) {
                    def s = ct.toString().trim()
                    if (s.isNumber()) {
                        long ts = Long.parseLong(s)
                        epochSec = (ts > 9999999999L) ? (ts / 1000L) : ts
                    }
                }
                if (epochSec != null) {
                    def date = new Date(epochSec * 1000L) // -> milliseconds
                    def sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss")
                    // sdf.setTimeZone(java.util.TimeZone.getTimeZone("UTC")) // Bật nếu muốn UTC
                    createdTimeStr = sdf.format(date)
                }
                if(item.attachment_types[j] == "image"){
                    def entity = [
                        "image_download_url": item.attachment_urls[j],
                        "type": item.attachment_types[j],
                        "post_id": item.post_id,
                        "platform": item.platform ?: item.domain,
                        "type": "post_image",
                        "created_time": createdTimeStr,
                        "source_type": 6,
                        "post_url": item.url,
                        "actor_username": item.actor_username,
                        "image_id": getID(item.attachment_urls[j])
                    ]
                    resultArr << entity
