                        "source_type": 6,
                        "post_url": item.url,
                        "actor_username": item.actor_username,
                        "video_id": getID(item.attachment_urls[j])
                    ]
                    resultArr << entity
                }
            }
        }
    }
    outputStream.write(JsonOutput.toJson(resultArr).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

if (resultArr.size() == 0) {
