                        // Fallback: dùng ZonedDateTime cho format có timezone phức tạp
                        def zdt = ZonedDateTime.parse(createdTime, DateTimeFormatter.ISO_DATE_TIME)
                        item.created_time = zdt.toInstant().epochSecond
