                }
            } else if (createdTime instanceof Number) {
                // Nếu đã là số: kiểm tra milliseconds (13 chữ số) hoặc seconds (10 chữ số)
                long ts = createdTime.toLong()
                item.created_time = (ts > 9999999999L) ? (ts / 1000L) : ts
            }
        }

        def attachment_urls = []
        def attachment_types = []

        if (item?.attachmentUrl instanceof List) {
            for (int j = 0; j < item.attachmentUrl.size(); j++) {
                attachment_urls << item.attachmentUrl[j]
                def type = item.attachmentType?.get(j)
                if (type?.contains('image')) {
                    attachment_types << 'image'
                } else if (type?.contains('video')) {
                    attachment_types << 'video'
                }
            }
        }

        item.remove('attachmentUrl')
        item.remove('attachmentType')

        if (item?.mentions instanceof List) {
            item.mention_tags_id = []
            item.mention_tags_name = []
            for (mention in item.mentions) {
                if (mention?.id) {
                    item.mention_tags_id << mention.id
                }
                if (mention?.global_name) {
                    item.mention_tags_name << mention.global_name
                }
            }
            item.remove('mentions')
        }

        if (item?.embeds instanceof List) {
            item.shared_snippet = null
            for (int j = 0; j < item.embeds.size(); j++) {
                def embed = item.embeds[j]
                if (embed == null) continue

                if (j == 0) {
                    if (embed?.url) item.shared_url = embed.url
                    item.shared_title = embed?.title ?: null
                    item.shared_snippet = embed?.description ?: null
                } else {
                    if (!item.shared_title && embed?.title) {
                        item.shared_title = embed.title
                    }
                    item.shared_snippet = (item.shared_snippet ?: "") + "\n" +
                                          (embed?.share_title ?: "") + "\n" +
                                          (embed?.description ?: "")
                }

                def thumbUrl = embed?.thumbnail?.url
                if (thumbUrl) {
                    attachment_urls << thumbUrl
                    attachment_types << 'image'
                }

                def videoUrl = embed?.video?.url
                if (videoUrl) {
                    attachment_urls << videoUrl
                    attachment_types << 'video'
                }

                def image = embed?.image
                if (image?.content_type && !image.content_type.contains('gif')) {
                    attachment_urls << image.url
                    attachment_types << 'image'
                }
            }
            item.remove('embeds')
        }

        def newPost = [:]
        def attachment_urls_newPost = []
        def attachment_types_newPost = []

        if (item?.referenced_message) {
            def ref = item.referenced_message
            if (ref?.id) {
                newPost.post_id = ref.id
                item.shared_id = newPost.post_id
            }
            newPost.message = ref?.content
            item.shared_snippet = newPost.message

            if (ref?.mentions instanceof List) {
                newPost.mention_tags_id = []
                newPost.mention_tags_name = []
                newPost.mention_tags_type = []
                for (mention in ref.mentions) {
                    if (mention?.id) {
                        newPost.mention_tags_id << mention.id
                        newPost.mention_tags_type << 'user'
                    }
                    if (mention?.global_name) {
                        newPost.mention_tags_name << mention.global_name
                    }
                }
            }

            newPost.url = "${referer}/${newPost.post_id}"

            def ts = ref?.timestamp
            if (ts instanceof String) {
                try {
                    def instant = Instant.parse(ts)
                    newPost.created_time = instant.epochSecond
                } catch (e) {
                    try {
                        // Fallback: dùng ZonedDateTime cho format có timezone phức tạp
                        def zdt = ZonedDateTime.parse(ts, DateTimeFormatter.ISO_DATE_TIME)
                        newPost.created_time = zdt.toInstant().epochSecond
                    } catch (e2) {
                        newPost.created_time = null
                    }
                }
            } else if (ts instanceof Number) {
                // Nếu đã là số: kiểm tra milliseconds (13 chữ số) hoặc seconds (10 chữ số)
                long val = ts.toLong()
                newPost.created_time = (val > 9999999999L) ? (val / 1000L) : val
            } else if (ts instanceof Date) {
                newPost.created_time = ts.time.intdiv(1000)
            }

            newPost.source_type = 6
            newPost.crawlers=["viewer_${adminId}"]

            def author = ref?.author
            if (author) {
                newPost.actor_id = author?.id
                newPost.actor_username = author?.username
                newPost.actor_name = author?.global_name
            }

            if (ref?.embeds instanceof List) {
                for (embed in ref.embeds) {
                    def thumbUrl = embed?.thumbnail?.url
                    if (thumbUrl) {
                        attachment_urls_newPost << thumbUrl
                        attachment_types_newPost << 'image'
                    }

                    def videoUrl = embed?.video?.url
                    if (videoUrl) {
                        attachment_urls_newPost << videoUrl
                        attachment_types_newPost << 'video'
                    }

                    def image = embed?.image
                    if (image?.content_type && !image.content_type.contains('gif')) {
                        attachment_urls_newPost << image.url
                        attachment_types_newPost << 'image'
                    }
                }

                newPost.attachment_urls = attachment_urls_newPost
                newPost.attachment_types = attachment_types_newPost
            }

            item.remove('referenced_message')
            resultArr << newPost
        }

        if (attachment_urls) {
            item.attachment_urls = attachment_urls
            item.attachment_types = attachment_types
        }
        if(adminId){
            item.crawlers=["viewer_${adminId}"]
        }


        item.source_type = 6

        resultArr << item
    }

    outputStream.write(JsonOutput.toJson(resultArr).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

session.transfer(flowFile, REL_SUCCESS)

