}
def hasError = false
flowFile = session.write(flowFile, { inputStream, outputStream ->
    def contentData = new String(inputStream.bytes, StandardCharsets.UTF_8)
    def originalBytes = contentData.getBytes(StandardCharsets.UTF_8)

    // Kiểm tra content có null hoặc rỗng không
    if (!contentData || contentData.trim().isEmpty()) {
        hasError = true
        outputStream.write(originalBytes)
        return
    }

    try {
        // Parse JSON từ contentData
        def jsonSlurper = new JsonSlurper()
        def jsonData = jsonSlurper.parseText(contentData)

        // Kiểm tra nếu jsonData là array và chỉ VALIDATE created_time là số 10 chữ số
        if (jsonData instanceof List) {
            for (item in jsonData) {
                if (item?.containsKey('created_time')) {
                    def ct = item.created_time
                    // created_time phải là số 10 chữ số (epoch seconds)
                    if (ct == null) {
                        hasError = true
                        outputStream.write(originalBytes)
                        return
                    }
                    if (ct instanceof Number) {
                        long ts = ct.toLong()
                        if (ts < 1000000000L || ts > 9999999999L) {
                            hasError = true
                            outputStream.write(originalBytes)
                            return
                        }
