                        def s = ct.toString().trim()
                        if (!(s ==~ /\d{10}/)) {
                            hasError = true
                            outputStream.write(originalBytes)
                            return
                        }
                    }
                }
            }
        }

        outputStream.write(JsonOutput.prettyPrint(JsonOutput.toJson(jsonData)).getBytes(StandardCharsets.UTF_8))
    } catch (Exception ex) {
        hasError = true
        outputStream.write(originalBytes)
    }
} as StreamCallback)

