def findCompleteJson(text, startIndex) {
    int openBraces = 0
    int closeBraces = 0
    for (int i = startIndex; i < text.length(); i++) {
        if (text[i] == '{') openBraces++
        if (text[i] == '}') closeBraces++
        if (openBraces > 0 && openBraces == closeBraces) {
            return text.substring(startIndex, i + 1)
        }
    }
    throw new IllegalArgumentException("Không tìm thấy JSON hoàn chỉnh từ vị trí $startIndex")
}

def fromText(text) {
    def res = []
    def pos = 0
    while (pos < text.length()) {
        def match = text.indexOf('{', pos)
        if (match == -1) break
        try {
            def jsonText = findCompleteJson(text, match)
            def result = new JsonSlurper().parseText(jsonText)
            res << result
            pos = match + jsonText.length()
        } catch (Exception e) {
            pos = match + 1
        }
    }
    return res
}

def findNodes(key, dataInput) {
