import org.apache.nifi.processor.io.StreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

def flowFile = session.get()
if (!flowFile) return

flowFile = session.write(flowFile, { inputStream, outputStream ->
    // Đọc input stream thành chuỗi
    def inputText = inputStream.getText("UTF-8")

    // Parse JSON từ chuỗi đầu vào
    def json = new JsonSlurper().parseText(inputText)

    // Danh sách chứa các URL
    def urls = []

    // Sinh các URL theo từng mục
    json.each { item ->
        def base = "https:${item.categoryUrl}"
        def cap = item.cap
        (1..60).each { page ->
            def url = "${base}/?ajax=true&isFirstRequest=true&page=${page}&spm=a211g0.flashsale.cate_${cap}.1820mHE4mHE47n"
            urls << url
        }
    }

    // Chuyển danh sách URL thành JSON
    def outputJson = JsonOutput.prettyPrint(JsonOutput.toJson([urls: urls]))

    // Ghi output ra stream
    outputStream.write(outputJson.getBytes("UTF-8"))
} as StreamCallback)

// Chuyển flowfile sang quan hệ thành công
session.transfer(flowFile, REL_SUCCESS)

import org.apache.nifi.processor.io.*
import org.apache.nifi.flowfile.FlowFile
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

def flowFile = session.get()
if (!flowFile) return

try {
    flowFile = session.write(flowFile, { inputStream, outputStream ->
        def inputJson = inputStream.getText("UTF-8")
        def parsed = new JsonSlurper().parseText(inputJson)

        def result = []

        parsed.each { outerKey, value ->
            def groupIndex = (outerKey as int) + 1  // key "0" → 1
            def urls = value.categoryUrl

            if (urls instanceof List) {
                urls.eachWithIndex { url, j ->
                    result << [
                        categoryUrl: url,
                        cap: "${groupIndex}.${j + 1}"
                    ]
                }
            }
        }

        def outputJson = JsonOutput.toJson(result)
        outputStream.write(outputJson.getBytes("UTF-8"))
    } as StreamCallback)

    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Lỗi khi xử lý JSON: ${e.message}", e)
    session.transfer(flowFile, REL_FAILURE)
}

import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.text.Normalizer

// Hàm loại bỏ dấu tiếng Việt và các dấu Unicode
def removeVietnameseAccents(String str) {
    if (!str) return ""
    String temp = Normalizer.normalize(str, Normalizer.Form.NFD)
    temp = temp.replaceAll("\\p{InCombiningDiacriticalMarks}+", "")
    temp = temp.replaceAll("đ", "d").replaceAll("Đ", "d")
    return temp
}

def flowFile = session.get()
if (!flowFile) return

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def text = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    def json = new JsonSlurper().parseText(text)

    if (json instanceof Map && json.sellerName instanceof String) {
        def originalName = json.sellerName.trim()
        if (originalName) {
            def normalizedName = removeVietnameseAccents(originalName)
                .toLowerCase()
                .replaceAll("[^a-z0-9\\s-]", "") // Chỉ giữ chữ thường, số, khoảng trắng, dấu '-'
                .replaceAll("[\\s]+", "-")       // Khoảng trắng liên tiếp thành 1 dấu '-'
                .replaceAll("-{2,}", "-")         // Nếu nhiều dấu '-' liên tiếp thì gộp 1 dấu
                .replaceAll("^-|-\$", "")         // Xóa dấu '-' đầu/cuối nếu có
            json.sellerName = normalizedName
        }
    }

    outputStream.write(JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

session.transfer(flowFile, REL_SUCCESS)

