// Hàm đệ quy để trải phẳng comments và replies
def flattenComments(comments, parentId, timestamp, flatList) {
    comments.each { comment ->
        def commentEpoch = comment.create_at ?: System.currentTimeMillis() / 1000
        def commentId = comment.id ?: UUID.randomUUID().toString()

        def commentDoc = comment.clone()
        commentDoc.remove('replies') // Remove replies to avoid duplication
        commentDoc['parent_id'] = parentId
        commentDoc['@timestamp'] = timestamp
        commentDoc['els_id'] = "${commentId}_${(commentEpoch / 3600).intValue()}"
        flatList << commentDoc

        // Xử lý replies nếu có
        if (comment.replies instanceof List && !comment.replies.isEmpty()) {
            flattenComments(comment.replies, commentId, timestamp, flatList)
        }
    }
}

