import org.apache.commons.io.IOUtils // Thư viện để đọc InputStream dễ dàng
import java.nio.charset.StandardCharsets // Để chỉ định mã hóa UTF-8
import groovy.json.JsonSlurper // Thư viện phân tích JSON của Groovy
import org.slf4j.LoggerFactory // Thư viện logging chuẩn của NiFi

// Lấy logger để ghi log (hữu ích cho việc gỡ lỗi)
def log = LoggerFactory.getLogger(getClass())

// Lấy một FlowFile từ hàng đợi đầu vào
def flowFile = session.get()
if (!flowFile) {
    // Nếu không có FlowFile nào, kết thúc script cho lần chạy này
    return
}

// Lấy UUID của FlowFile để ghi log dễ theo dõi hơn
def ffUUID = flowFile.getAttribute('uuid')

try {
    // ---- Bước 1: Đọc nội dung FlowFile ----
    def content = session.read(flowFile).withStream { inputStream ->
        IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    }
    // (Tùy chọn) Ghi log nội dung để kiểm tra nếu cần
    // log.debug("Nội dung FlowFile {}: {}", ffUUID, content)

    // ---- Bước 2: Phân tích JSON ----
    def json = new JsonSlurper().parseText(content)
    log.info("Đã phân tích JSON thành công cho FlowFile {}", ffUUID)

    // ---- Bước 3: Kiểm tra cấu trúc JSON ----
    boolean structureOk = false // Biến cờ để theo dõi cấu trúc có hợp lệ không
    String failureReason = "Cấu trúc JSON không xác định" // Lý do thất bại mặc định

    // Kiểm tra 1: json phải là Map (object) và có key 'code' và key 'result'
    if (json instanceof Map && json.containsKey('code') && json.containsKey('result')) {
        // Kiểm tra 2: Giá trị của 'result' phải là Map (object)
        def resultValue = json.result
        if (resultValue instanceof Map) {
             // Kiểm tra 3: Giá trị của 'result' phải có key 'layout'
            if (resultValue.containsKey('layout')) {
                 // Nếu tất cả các kiểm tra đều qua, cấu trúc OK
                structureOk = true
                log.debug("FlowFile {} có cấu trúc 'code', 'result' (là Map), và 'result.layout' hợp lệ.", ffUUID)
            } else {
                // 'result' không chứa key 'layout'
                failureReason = "Trường 'result' là Map nhưng thiếu trường con 'layout'"
                 log.warn("FlowFile {} thất bại kiểm tra: {}", ffUUID, failureReason)
            }
        } else {
             // Giá trị của 'result' không phải là Map (object)
             failureReason = "Trường 'result' không phải là Map (object)"
             log.warn("FlowFile {} thất bại kiểm tra: {}", ffUUID, failureReason)
        }
    } else {
        // json không phải là Map hoặc thiếu key 'code' hoặc thiếu key 'result'
        failureReason = "JSON không phải là Map hoặc thiếu trường 'code' hoặc 'result'"
        log.warn("FlowFile {} thất bại kiểm tra: {}", ffUUID, failureReason)
    }

    // ---- Bước 4: Quyết định xử lý dựa trên kết quả kiểm tra ----
    if (structureOk) {
        // Nếu cấu trúc hợp lệ, chuyển đến SUCCESS
        log.info("FlowFile {} đáp ứng cấu trúc yêu cầu. Chuyển đến REL_SUCCESS.", ffUUID)
        session.transfer(flowFile, REL_SUCCESS)
    } else {
        // Nếu cấu trúc không hợp lệ, **XÓA** FlowFile
        log.warn("FlowFile {} không đáp ứng cấu trúc yêu cầu ('code', 'result' là Map chứa 'layout'). Lý do: {}. Xóa FlowFile.", ffUUID, failureReason)
        session.remove(flowFile)
    }

} catch (Exception e) {
    // ---- Bước 5: Xử lý lỗi (ví dụ: JSON không hợp lệ, lỗi đọc file) ----
    // Ghi log chi tiết về lỗi
    log.error("Xử lý FlowFile {} thất bại do lỗi: {}. Xóa FlowFile.", ffUUID, e.getMessage(), e)
    // **XÓA** FlowFile gốc nếu có lỗi
    session.remove(flowFile)
}

